    """Return invoice due dates as datetimes, supporting day/month/year and year-month-day formats."""
    return pd.to_datetime(invoices["due"], format="mixed", dayfirst=True)
```

```python
import pandas as pd


def parse_due_dates(invoices):
    """Return invoice due dates, supporting mixed day/month/year and year-month-day formats."""
    return pd.to_datetime(invoices["due"], format="mixed", dayfirst=True)
```

```python
def busiest_week(stamps):
    """Return the week of the year that occurs most often among the timestamps of a DatetimeArray."""
    weeks = stamps.isocalendar().week.tolist()
    return max(sorted(set(weeks)), key=weeks.count)
```

